import React from 'react';
import './SearchListItem.css';
import Button from "../common/Button";

const SearchListItem = ({ name, distance, tag, type, description, free_cancel, price, rate, rate_text, image_url }) => {
  return (
    <article className="search-list-item">
      {/* Hình ảnh của khách sạn */}
      <img src={image_url} alt={name} className="search-list-item__image" />

      {/* Thông tin khách sạn */}
      <div className="search-list-item__details">
        <h3 className="hotel-name">{name}</h3>
        <p className="hotel-distance">{distance} from center</p>

        <span className="hotel-tag" aria-label={tag}>{tag}</span>

        <p className="hotel-description">{description}</p>
        <p className="hotel-type">{type}</p>

        {/* Điều kiện hủy miễn phí, chỉ hiển thị nếu có */}
        {free_cancel && (
          <p className="hotel-free-cancel">
            <span className="green-text">Free cancellation</span>
            <br />
            You can cancel later, so lock in this great price today!
          </p>
        )}
      </div>

      {/* Thông tin giá cả và đánh giá */}
      <div className="search-list-item__price">
        <div className="hotel-rate" aria-label={`${rate_text} rating`}>
          <strong>{rate_text}</strong>
          <div className="hotel-score" aria-hidden="true">{rate}</div>
        </div>

        <div className="hotel-price" aria-label={`Price: $${price}`}>
          ${price}
        </div>
        <span className="hotel-taxes">Includes taxes and fees</span>
          <Button text="See availability"  classNames="primary" />
        {/*<button className="see-availability-btn" aria-label={`See availability for ${name}`}>*/}
        {/* */}
        {/*</button>*/}
      </div>
    </article>
  );
};

export default SearchListItem;
